def write_html_report(opt, result_df, failed_df, homo_1):
    path = opt.path
    GC = result_df[['Product GC percent']].apply(lambda x: round(x, 0))
    GC = GC.groupby('Product GC percent')['Product GC percent'].count()
    x_gc = GC.index.tolist()
    y_gc = GC.tolist()
    # y_gc = list(map(lambda x: round(x / GC.sum(), 4), GC.tolist()))
    amp_size = result_df[['product size']].groupby('product size')['product size'].count()
    x_amp = amp_size.index.tolist()
    y_amp = amp_size.tolist()
    # y_amp = list(map(lambda x: round(x / amp_size.sum(), 4), amp_size.tolist()))
    try:
        os.remove(path + f'/{opt.order_num}.html')
    except:
        logging.info("The first to create SummaryReport.html")
    # nhr.Report(path + '/SummaryReport.html', x_gc, y_gc, x_amp, y_amp, homo_1, failed_df, opt.order_num, opt.user_info)

    Report(path + f'/{opt.order_num}.html', x_gc, y_gc, x_amp, y_amp, homo_1, failed_df, opt.order_num)


class Report:
    def __init__(self, file, gc_x, gc_y, len_x, len_y, homo_1, FD, order_num):
        self.order_num = order_num
        self.logo_content = self.print_logo()
        # self.user_info = user_info
        self.print_header(file)
        self.print_summary(file)
        self.print_gc_distribution(file, gc_x, gc_y)
        self.print_amplicon(file, len_x, len_y)
        self.print_homo_pos(file, homo_1)
        # self.print_abandon_homo(file, homo_0)
        self.print_failed_region(file, FD)

    def print_header(self, file):
        with open(file, 'a+') as f:
            f.write('<html><head><meta http-equiv=\"content-type\" content=\"text/html;charset=utf-8\" />')
            f.write(f'<title>CAMPs Report of {self.order_num} </title>')
        self.print_js(file)
        self.print_css(file)
        with open(file, 'a+') as f:
            f.write(f"</head>\n{self.logo_content}<body>"
                    "<div class='header'>"
                    "<div id='container'><h1 style='text-align:left;'>"
                    "<a target='_blank' style='color:#000000;text-decoration:none;'>"
                    f"CAMPs Report of {self.order_num}</a>")

